import { Express, Request, Response } from 'express';
import { Dependencies } from './dependencies';
import { OrderState } from '../domain/Order';

export function setupRoutes(app: Express, deps: Dependencies): void {
  // Place order
  app.post('/api/orders', (req: Request, res: Response) => {
    try {
      const { customerId, items } = req.body;
      if (!customerId || !items || !Array.isArray(items)) {
        res.status(400).json({ error: 'Invalid request body' });
        return;
      }
      const order = deps.placeOrderUseCase.execute({ customerId, items });
      res.status(201).json(order);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });

  // Update order state
  app.patch('/api/orders/:orderId/state', (req: Request, res: Response) => {
    try {
      const { orderId } = req.params as { orderId: string };
      const { state } = req.body as { state?: string };
      if (!state) {
        res.status(400).json({ error: 'State is required' });
        return;
      }
      const order = deps.updateOrderStateUseCase.execute({
        orderId,
        newState: state as OrderState,
      });
      res.json(order);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });

  // Cancel order
  app.post('/api/orders/:orderId/cancel', (req: Request, res: Response) => {
    try {
      const { orderId } = req.params as { orderId: string };
      const order = deps.cancelOrderUseCase.execute(orderId);
      res.json(order);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });

  // List orders by state
  app.get('/api/orders', (req: Request, res: Response) => {
    try {
      const { state } = req.query as { state?: string };
      if (!state || typeof state !== 'string') {
        res.status(400).json({ error: 'State query parameter is required' });
        return;
      }
      const orders = deps.listOrdersByStateUseCase.execute(state as OrderState);
      res.json(orders);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });

  // Get order by ID
  app.get('/api/orders/:orderId', (req: Request, res: Response) => {
    try {
      const { orderId } = req.params as { orderId: string };
      const order = deps.orderRepository.getById(orderId);
      if (!order) {
        res.status(404).json({ error: 'Order not found' });
        return;
      }
      res.json(order);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });

  // Get stock levels
  app.get('/api/stock', (req: Request, res: Response) => {
    try {
      const stockLevels = deps.getStockLevelsUseCase.execute();
      res.json(stockLevels);
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      res.status(400).json({ error: message });
    }
  });
}

